137|func (r *scheduleRepoImpl) RangeTimeoutReleaseQueue(ctx context.Context, timeout, offset, count int64) ([]*biz.ReleaseTask, error) {
138|	result, err := r.redisRepo.ZRangeByScoreWithScores(ctx, CACHE_KEY_RELEASE_QUEUE, &redis.ZRangeBy{
139|		Min:    "0",
140|		Max:    strconv.FormatInt(timeout, 10),
141|		Offset: offset,
142|		Count:  count,
143|	})
144|	if err != nil {
145|		return nil, err
146|	}
147|	var tasks []*biz.ReleaseTask
148|	for _, item := range result {
149|		member := item.Member.(string)
150|		parts := strings.Split(member, "-")
151|		if len(parts) != 3 {
152|			continue
153|		}
154|		uuid, err := strconv.ParseUint(parts[0], 10, 64)
